"""Fuzz the request surface: every input must produce JSON output, never a crash."""
import io
import json
import random
import sys

sys.path.insert(0, '/workspace/submission')
import formats
import pipeline

BAD = []


def attempt(data, label):
    try:
        req = formats.read_request(io.BytesIO(data))
    except (ValueError, UnicodeError, RecursionError, MemoryError):
        return
    except Exception as exc:
        BAD.append((label, 'parse', repr(exc), data[:200]))
        return
    try:
        out = pipeline.execute(req)
        json.dumps(out, separators=(',', ':'), allow_nan=False)
    except Exception as exc:
        BAD.append((label, 'execute', repr(exc), data[:4000]))


def mutate(rnd, obj, depth=0):
    """Randomly corrupt a valid request structure."""
    kind = rnd.randrange(9)
    if kind == 0:
        return rnd.choice([None, True, False, 0, -1, 1.5, '', [], {}, 'x', 3029, 1514])
    if isinstance(obj, dict):
        keys = list(obj)
        if not keys:
            return obj
        k = rnd.choice(keys)
        if kind == 1:
            del obj[k]
        elif kind == 2:
            obj[k] = mutate(rnd, obj[k], depth+1)
        elif kind == 3:
            obj[rnd.choice(['extra', 'Capacity', 'id2', ''])] = 1
        return obj
    if isinstance(obj, list):
        if not obj:
            return rnd.choice([None, 0, 'x', [0]])
        i = rnd.randrange(len(obj))
        if kind == 4:
            del obj[i]
        elif kind == 5:
            obj[i] = mutate(rnd, obj[i], depth+1)
        elif kind == 6:
            obj.append(rnd.choice([0, None, 'x', [], {}]))
        elif kind == 7 and len(obj) > 3:
            obj[i], obj[0] = obj[0], obj[i]
        return obj
    if isinstance(obj, int) and not isinstance(obj, bool):
        return rnd.choice([obj+1, obj-1, -obj, 2**70, obj*1000, 1514, 3028, 3029, 0])
    if isinstance(obj, str):
        return rnd.choice([obj+'x', '', ' ', obj.upper(), 5, None, '\u00e9'])
    return obj


def base_request(rnd):
    classes = rnd.randint(1, 3)
    width = rnd.randint(2, 4)
    ndisc = rnd.randint(0, 6)
    disc = []
    for _ in range(ndisc):
        n = rnd.randint(2, 10)
        vals = [rnd.choice([0, 1, 100, 1513, 1515, 1600, 3028, rnd.randint(0, 3028)]) for _ in range(n)]
        vals = [v+1 if v == 1514 else v for v in vals]
        if rnd.random() < 0.3:
            vals = vals+[1514]*rnd.randint(1, 3)
        acts = [rnd.randint(0, 200) for _ in range(len(vals))]
        disc.append({'class': rnd.randrange(classes), 'values': vals, 'activation': acts})
    def rows():
        out = [{'class': c, 'values': [rnd.choice([0, 100, 1513, 1515, 1600, 3028, rnd.randint(0, 3028)])
                                       for _ in range(rnd.randint(0, 6))]} for c in range(classes)]
        for r in out:
            r['values'] = [v+1 if v == 1514 else v for v in r['values']]
        return out
    rel = {'id': 'r', 'classes': classes, 'width': width,
           'eps': [rnd.randint(0, 2000), rnd.randint(1, 100)],
           'ratio': [rnd.randint(0, 4), rnd.randint(1, 8)],
           'threshold': [rnd.randint(0, 20000), rnd.randint(1, 5)],
           'mode': rnd.choice(['range', 'exact']),
           'packet_limit': rnd.randint(width, 12), 'idle_us': rnd.choice([0, 3, 100]),
           'discovery': disc, 'train': rows(), 'validation': rows()}
    ops = []
    if rnd.random() < 0.9:
        ops.append(['install', 'r'])
    for f in range(rnd.randint(0, 3)):
        fid = 'f%d' % f
        ops.append(['open', fid])
        ts = 0
        for _ in range(rnd.randint(0, 8)):
            ts += rnd.choice([0, 1, 5, 200])
            ops.append(['packet', fid, ts, rnd.randint(0, 1), rnd.randint(1, 1514)])
        ops.append(['close', fid])
    return {'capacity': {'range': rnd.randint(0, 4), 'exact': rnd.randint(0, 4)},
            'releases': [rel], 'blocks': [ops]}


def main():
    rnd = random.Random(int(sys.argv[2]) if len(sys.argv) > 2 else 0)
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 3000
    accepted = 0
    for i in range(n):
        req = base_request(rnd)
        for _ in range(rnd.randint(1, 4)):
            req = mutate(rnd, req)
        data = json.dumps(req).encode() if rnd.random() < 0.9 else \
            json.dumps(req).encode()[:rnd.randint(1, 400)]
        attempt(data, 'mutated')
        if rnd.random() < 0.3:
            attempt(bytearray(rnd.randbytes(rnd.randint(0, 300))), 'random bytes')
    print('fuzz done; crashes:', len(BAD))
    for item in BAD[:6]:
        print(' ', item[0], item[1], item[2])
        print('   data:', item[3][:400])


if __name__ == '__main__':
    main()
